xinshengCustomCss:
/*⁣‌‍​⁠‍​‍​​​⁠⁠‌​‍⁠‌‍‍‌‌​​‍⁠‌⁠​​⁠⁠​‌‌‍​‍​‌‍‍‍‍‍​‍‌‌‌⁠‌‍⁠⁠​⁠⁠‍​⁠‌‍⁠‌⁣ ==========================================================
   地球Online梦向论坛
   首页入口 + 独立帖子页 + 返回论坛
   ========================================================== */


/* ==========================================================
   1. 整体容器
   ========================================================== */

.xt-root {
  --xt-bg: #ffffff;
  --xt-text: #171717;
  --xt-sub: #74818a;
  --xt-muted: #a1a9af;
  --xt-line: #e7eaec;
  --xt-soft: #f5f6f7;
  --xt-blue: #34758f;
  --xt-pink: #bd718e;

  position: relative;

  width: 100%;
  max-width: 460px;
  height: 76vh !important;
  min-height: 520px;
  max-height: 760px !important;

  margin: 0 auto;
  padding: 58px 0 0 !important;

  box-sizing: border-box;

  overflow-y: auto !important;
  overflow-x: hidden !important;

  -webkit-overflow-scrolling: touch !important;
  overscroll-behavior-y: contain;
  touch-action: pan-y !important;

  color: var(--xt-text) !important;
  background: #ffffff !important;

  border: 1px solid #e7e9eb !important;
  border-radius: 18px !important;

  box-shadow:
    0 10px 35px rgba(0, 0, 0, 0.08) !important;

  font-family:
    -apple-system,
    BlinkMacSystemFont,
    "PingFang SC",
    "Microsoft YaHei",
    sans-serif !important;

  scrollbar-width: thin;
  scrollbar-color: #d5dadd transparent;
}


/* ==========================================================
   2. 内容区域
   ========================================================== */

.xt-content {
  position: relative;

  width: 100%;
  min-height: 100%;

  margin: 0 !important;
  padding: 0 0 16px !important;

  box-sizing: border-box;

  overflow: visible !important;
  background: #ffffff !important;
}


/* ==========================================================
   3. 顶部装饰
   ========================================================== */

.xt-root::before {
  content: "‹";

  position: absolute;
  top: 4px;
  left: 18px;
  z-index: 20;

  color: #111111;

  font-family: Arial, sans-serif;
  font-size: 48px;
  font-weight: 300;
  line-height: 44px;

  pointer-events: none;
}

.xt-root::after {
  content: "•••";

  position: absolute;
  top: 13px;
  right: 19px;
  z-index: 20;

  color: #687984;

  font-family: Arial, sans-serif;
  font-size: 16px;
  font-weight: 700;
  letter-spacing: 3px;

  pointer-events: none;
}


/* ==========================================================
   4. char资料区域
   使用已经成功显示头像的 @row + @image
   ========================================================== */

.xt-content > .xt-row:first-child {
  display: grid !important;
  grid-template-columns: 58px minmax(0, 1fr) !important;
  align-items: center !important;
  gap: 14px !important;

  width: 100%;

  margin: 0 !important;
  padding: 20px 22px 22px !important;

  box-sizing: border-box;

  background: #ffffff !important;

  border: 0 !important;
  border-bottom: 1px solid var(--xt-line) !important;
  border-radius: 0 !important;

  box-shadow: none !important;
}


/* 头像本体 */

.xt-content > .xt-row:first-child > .xt-image {
  display: block !important;

  width: 58px !important;
  height: 58px !important;
  min-width: 58px !important;
  max-width: 58px !important;

  margin: 0 !important;
  padding: 0 !important;

  box-sizing: border-box;

  object-fit: cover !important;
  object-position: center !important;

  background-color: #eeeeee !important;
  background-position: center !important;
  background-size: cover !important;
  background-repeat: no-repeat !important;

  border: 0 !important;
  border-radius: 50% !important;

  overflow: hidden !important;
  box-shadow: none !important;
}


/* 兼容头像外面还有容器的情况 */

.xt-content > .xt-row:first-child > .xt-image img,
.xt-content > .xt-row:first-child img.xt-image {
  display: block !important;

  width: 100% !important;
  height: 100% !important;

  margin: 0 !important;
  padding: 0 !important;

  object-fit: cover !important;
  object-position: center !important;

  border-radius: 50% !important;
}


/* char名字 */

.xt-text-charName {
  display: block !important;

  min-width: 0;

  margin: 0 !important;
  padding: 0 !important;

  color: #171717 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 19px !important;
  font-weight: 760 !important;
  line-height: 1.35 !important;

  overflow-wrap: anywhere;
}

.xt-text-charName::after {
  content: "@earth_online";

  display: block;

  margin-top: 4px;

  color: #788690;

  font-size: 13px;
  font-weight: 400;
  line-height: 1.3;
}


/* ==========================================================
   5. 所有卡片基础清理
   ========================================================== */

.xt-card {
  box-sizing: border-box;

  box-shadow: none !important;
}

.xt-card-title {
  box-sizing: border-box;
}


/* ==========================================================
   6. 识别论坛首页卡片
   首页卡片同时拥有三个入口按钮
   ========================================================== */

.xt-card:has(.xt-action-1):has(.xt-action-2):has(.xt-action-3) {
  display: block !important;

  width: calc(100% - 28px);

  margin: 14px !important;
  padding: 5px 0 8px !important;

  background: #ffffff !important;

  border: 1px solid #e3e7e9 !important;
  border-radius: 16px !important;

  overflow: hidden !important;
}

.xt-card:has(.xt-action-1):has(.xt-action-2):has(.xt-action-3)
  > .xt-card-title {
  display: block !important;

  margin: 0 !important;
  padding: 17px 18px 14px !important;

  color: #171717 !important;
  background: transparent !important;

  border: 0 !important;
  border-bottom: 1px solid #eef0f1 !important;

  font-size: 17px !important;
  font-weight: 750 !important;
  line-height: 1.4 !important;
}


/* ==========================================================
   7. 三个论坛入口
   ========================================================== */

.xt-action-1,
.xt-action-2,
.xt-action-3 {
  position: relative;

  display: block !important;

  width: calc(100% - 24px);
  min-height: 82px;

  margin: 12px !important;
  padding: 15px 46px 14px 60px !important;

  box-sizing: border-box;

  color: #171717 !important;
  background: #f7f8f9 !important;

  border: 1px solid #edf0f2 !important;
  border-radius: 13px !important;

  font-size: 0 !important;
  line-height: 1 !important;

  cursor: pointer;
  overflow: hidden;

  transition:
    background-color 0.18s ease,
    transform 0.18s ease;
}

.xt-action-1:active,
.xt-action-2:active,
.xt-action-3:active {
  background: #f0f2f3 !important;
  transform: scale(0.987);
}


/* 左侧编号 */

.xt-action-1::after,
.xt-action-2::after,
.xt-action-3::after {
  position: absolute;
  left: 15px;
  top: 18px;

  display: flex;
  align-items: center;
  justify-content: center;

  width: 34px;
  height: 34px;

  color: #ffffff;
  background: #171717;

  border-radius: 10px;

  font-family: Arial, sans-serif;
  font-size: 12px;
  font-weight: 750;
  line-height: 1;
}

.xt-action-1::after {
  content: "01";
}

.xt-action-2::after {
  content: "02";
}

.xt-action-3::after {
  content: "03";
}


/* 入口标题与说明 */

.xt-action-1::before,
.xt-action-2::before,
.xt-action-3::before {
  display: block;

  color: #171717;

  font-size: 17px;
  font-weight: 750;
  line-height: 1.35;

  white-space: pre-line;
}

.xt-action-1::before {
  content: "梦向吐槽\A养成求助、行为吐槽与同担争论";
}

.xt-action-2::before {
  content: "星月传话\A梦占、塔罗、传讯与匿名树洞";
}

.xt-action-3::before {
  content: "梦图梦稿\A寻找画师、文手与梦向委托";
}


/* 入口右侧箭头 */

.xt-action-1 {
  background-image:
    linear-gradient(45deg, transparent 48%, #9ba5ab 49% 54%, transparent 55%),
    linear-gradient(-45deg, transparent 48%, #9ba5ab 49% 54%, transparent 55%) !important;

  background-position:
    calc(100% - 22px) calc(50% - 4px),
    calc(100% - 22px) calc(50% + 4px) !important;

  background-size: 9px 9px !important;
  background-repeat: no-repeat !important;
}

.xt-action-2 {
  background-image:
    linear-gradient(45deg, transparent 48%, #9ba5ab 49% 54%, transparent 55%),
    linear-gradient(-45deg, transparent 48%, #9ba5ab 49% 54%, transparent 55%) !important;

  background-position:
    calc(100% - 22px) calc(50% - 4px),
    calc(100% - 22px) calc(50% + 4px) !important;

  background-size: 9px 9px !important;
  background-repeat: no-repeat !important;
}

.xt-action-3 {
  background-image:
    linear-gradient(45deg, transparent 48%, #9ba5ab 49% 54%, transparent 55%),
    linear-gradient(-45deg, transparent 48%, #9ba5ab 49% 54%, transparent 55%) !important;

  background-position:
    calc(100% - 22px) calc(50% - 4px),
    calc(100% - 22px) calc(50% + 4px) !important;

  background-size: 9px 9px !important;
  background-repeat: no-repeat !important;
}


/* 说明文字 */

.xt-action-1::first-line,
.xt-action-2::first-line,
.xt-action-3::first-line {
  color: #171717;
}


/* ==========================================================
   8. 三个帖子页面默认隐藏
   ========================================================== */

.xt-card:has(.xt-text-rantTitle),
.xt-card:has(.xt-text-moonTitle),
.xt-card:has(.xt-text-draftTitle) {
  display: none !important;

  width: 100%;

  margin: 0 !important;
  padding: 0 !important;

  background: #ffffff !important;

  border: 0 !important;
  border-radius: 0 !important;

  overflow: visible !important;
}


/* ==========================================================
   9. 点击入口后显示对应帖子
   ========================================================== */

#xt-t1:checked ~ .xt-content
  .xt-card:has(.xt-text-rantTitle) {
  display: block !important;
}

#xt-t2:checked ~ .xt-content
  .xt-card:has(.xt-text-moonTitle) {
  display: block !important;
}

#xt-t3:checked ~ .xt-content
  .xt-card:has(.xt-text-draftTitle) {
  display: block !important;
}


/* ==========================================================
   10. 进入详情页后，首页卡片变成返回栏
   ========================================================== */

#xt-t1:checked ~ .xt-content
  .xt-card:has(.xt-action-1):has(.xt-action-2):has(.xt-action-3),
#xt-t2:checked ~ .xt-content
  .xt-card:has(.xt-action-1):has(.xt-action-2):has(.xt-action-3),
#xt-t3:checked ~ .xt-content
  .xt-card:has(.xt-action-1):has(.xt-action-2):has(.xt-action-3) {
  width: 100%;

  margin: 0 !important;
  padding: 0 !important;

  border: 0 !important;
  border-bottom: 8px solid #f3f5f6 !important;
  border-radius: 0 !important;
}


/* 隐藏首页标题 */

#xt-t1:checked ~ .xt-content
  .xt-card:has(.xt-action-1) > .xt-card-title,
#xt-t2:checked ~ .xt-content
  .xt-card:has(.xt-action-1) > .xt-card-title,
#xt-t3:checked ~ .xt-content
  .xt-card:has(.xt-action-1) > .xt-card-title {
  display: none !important;
}


/* 进入某页后只留下对应按钮 */

#xt-t1:checked ~ .xt-content .xt-action-2,
#xt-t1:checked ~ .xt-content .xt-action-3 {
  display: none !important;
}

#xt-t2:checked ~ .xt-content .xt-action-1,
#xt-t2:checked ~ .xt-content .xt-action-3 {
  display: none !important;
}

#xt-t3:checked ~ .xt-content .xt-action-1,
#xt-t3:checked ~ .xt-content .xt-action-2 {
  display: none !important;
}


/* 返回按钮统一样式 */

#xt-t1:checked ~ .xt-content .xt-action-1,
#xt-t2:checked ~ .xt-content .xt-action-2,
#xt-t3:checked ~ .xt-content .xt-action-3 {
  display: block !important;

  width: 100%;
  min-height: 52px;

  margin: 0 !important;
  padding: 15px 20px 15px 45px !important;

  color: #171717 !important;
  background: #ffffff !important;

  border: 0 !important;
  border-radius: 0 !important;

  background-image: none !important;

  font-size: 0 !important;
  transform: none !important;
}


/* 返回箭头 */

#xt-t1:checked ~ .xt-content .xt-action-1::after,
#xt-t2:checked ~ .xt-content .xt-action-2::after,
#xt-t3:checked ~ .xt-content .xt-action-3::after {
  content: "‹";

  position: absolute;
  top: 5px;
  left: 18px;

  display: block;

  width: auto;
  height: auto;

  color: #171717;
  background: transparent;

  font-family: Arial, sans-serif;
  font-size: 38px;
  font-weight: 300;
  line-height: 40px;
}


/* 返回文字 */

#xt-t1:checked ~ .xt-content .xt-action-1::before,
#xt-t2:checked ~ .xt-content .xt-action-2::before,
#xt-t3:checked ~ .xt-content .xt-action-3::before {
  content: "返回论坛板块";

  color: #171717;

  font-size: 15px;
  font-weight: 650;
  line-height: 22px;
}


/* ==========================================================
   11. 帖子板块标签
   ========================================================== */

.xt-card:has(.xt-text-rantTitle) > .xt-card-title,
.xt-card:has(.xt-text-moonTitle) > .xt-card-title,
.xt-card:has(.xt-text-draftTitle) > .xt-card-title {
  display: inline-flex !important;
  align-items: center !important;

  width: auto !important;

  margin: 18px 20px 5px !important;
  padding: 5px 9px !important;

  color: #4f6875 !important;
  background: #f1f5f7 !important;

  border: 0 !important;
  border-radius: 6px !important;

  font-size: 12px !important;
  font-weight: 680 !important;
  line-height: 1.35 !important;
}


/* ==========================================================
   12. 帖子标题
   ========================================================== */

.xt-text-rantTitle,
.xt-text-moonTitle,
.xt-text-draftTitle {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 11px 20px 0 !important;

  box-sizing: border-box;

  color: #111111 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 22px !important;
  font-weight: 790 !important;
  line-height: 1.45 !important;
  letter-spacing: -0.3px !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}


/* ==========================================================
   13. 帖子正文
   ========================================================== */

.xt-text-rantPost,
.xt-text-moonPost,
.xt-text-draftPost {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 14px 20px 18px !important;

  box-sizing: border-box;

  color: #282828 !important;
  background: transparent !important;

  border: 0 !important;
  border-radius: 0 !important;
  border-bottom: 8px solid #f3f5f6 !important;

  box-shadow: none !important;

  font-size: 16px !important;
  font-weight: 400 !important;
  line-height: 1.75 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.xt-text-rantPost::after,
.xt-text-moonPost::after,
.xt-text-draftPost::after {
  content: "◯　　　　⇄　　　　♡　　　　⌯";

  display: block;

  margin-top: 16px;
  padding-top: 14px;

  color: #788892;

  border-top: 1px solid #e7eaec;

  font-family: Arial, sans-serif;
  font-size: 19px;
  line-height: 1;
  text-align: center;
}


/* ==========================================================
   14. 所有评论昵称
   ========================================================== */

.xt-text-rantName1,
.xt-text-rantName2,
.xt-text-rantName3,
.xt-text-rantName4,
.xt-text-rantName5,
.xt-text-moonName1,
.xt-text-moonName2,
.xt-text-moonName3,
.xt-text-moonName4,
.xt-text-moonName5,
.xt-text-draftName1,
.xt-text-draftName2,
.xt-text-draftName3,
.xt-text-draftName4,
.xt-text-draftName5 {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 16px 20px 5px 68px !important;

  box-sizing: border-box;

  color: #202020 !important;
  background: #ffffff !important;

  border: 0 !important;
  border-radius: 0 !important;

  box-shadow: none !important;

  font-size: 14px !important;
  font-weight: 720 !important;
  line-height: 1.4 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}


/* 评论头像只做小色块，不冒充真实头像 */

.xt-text-rantName1,
.xt-text-rantName2,
.xt-text-rantName3,
.xt-text-rantName4,
.xt-text-rantName5,
.xt-text-moonName1,
.xt-text-moonName2,
.xt-text-moonName3,
.xt-text-moonName4,
.xt-text-moonName5,
.xt-text-draftName1,
.xt-text-draftName2,
.xt-text-draftName3,
.xt-text-draftName4,
.xt-text-draftName5 {
  position: relative;
}

.xt-text-rantName1::before,
.xt-text-rantName2::before,
.xt-text-rantName3::before,
.xt-text-rantName4::before,
.xt-text-rantName5::before,
.xt-text-moonName1::before,
.xt-text-moonName2::before,
.xt-text-moonName3::before,
.xt-text-moonName4::before,
.xt-text-moonName5::before,
.xt-text-draftName1::before,
.xt-text-draftName2::before,
.xt-text-draftName3::before,
.xt-text-draftName4::before,
.xt-text-draftName5::before {
  content: "";

  position: absolute;
  top: 16px;
  left: 20px;

  width: 34px;
  height: 34px;

  background:
    linear-gradient(
      145deg,
      #dfe8ec,
      #becdd4
    );

  border-radius: 50%;
}


/* ==========================================================
   15. 评论正文
   ========================================================== */

.xt-text-rantComment1,
.xt-text-rantComment2,
.xt-text-rantComment3,
.xt-text-rantComment4,
.xt-text-rantComment5,
.xt-text-moonComment1,
.xt-text-moonComment2,
.xt-text-moonComment3,
.xt-text-moonComment4,
.xt-text-moonComment5,
.xt-text-draftComment1,
.xt-text-draftComment2,
.xt-text-draftComment3,
.xt-text-draftComment4,
.xt-text-draftComment5 {
  display: block !important;

  width: 100%;

  margin: 0 !important;
  padding: 0 20px 15px 68px !important;

  box-sizing: border-box;

  color: #2c2c2c !important;
  background: #ffffff !important;

  border: 0 !important;
  border-radius: 0 !important;
  border-bottom: 1px solid #e7eaec !important;

  box-shadow: none !important;

  font-size: 14px !important;
  font-weight: 400 !important;
  line-height: 1.68 !important;

  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.xt-text-rantComment1::after,
.xt-text-rantComment2::after,
.xt-text-rantComment3::after,
.xt-text-rantComment4::after,
.xt-text-rantComment5::after,
.xt-text-moonComment1::after,
.xt-text-moonComment2::after,
.xt-text-moonComment3::after,
.xt-text-moonComment4::after,
.xt-text-moonComment5::after,
.xt-text-draftComment1::after,
.xt-text-draftComment2::after,
.xt-text-draftComment3::after,
.xt-text-draftComment4::after,
.xt-text-draftComment5::after {
  content: "回复　·　赞";

  display: block;

  margin-top: 10px;

  color: #9ca6ac;

  font-size: 11px;
  line-height: 1.3;
}


/* ==========================================================
   16. char本人回复
   ========================================================== */

.xt-text-rantName5,
.xt-text-moonName5,
.xt-text-draftName5 {
  color: #ae5c7b !important;
  background:
    linear-gradient(
      90deg,
      rgba(253, 229, 238, 0.32),
      #ffffff 58%
    ) !important;
}

.xt-text-rantName5::after,
.xt-text-moonName5::after,
.xt-text-draftName5::after {
  content: "楼主";

  display: inline-block;

  margin-left: 7px;
  padding: 2px 6px;

  color: #b65f80;
  background: #fde5ee;

  border-radius: 5px;

  font-size: 10px;
  font-weight: 650;
  line-height: 1.3;
}

.xt-text-rantName5::before,
.xt-text-moonName5::before,
.xt-text-draftName5::before {
  background:
    linear-gradient(
      145deg,
      #f1bfd1,
      #d98fab
    );
}

.xt-text-rantComment5,
.xt-text-moonComment5,
.xt-text-draftComment5 {
  background:
    linear-gradient(
      90deg,
      rgba(253, 229, 238, 0.32),
      #ffffff 58%
    ) !important;
}


/* ==========================================================
   17. 详情页状态下隐藏无关帖子
   ========================================================== */

#xt-t1:checked ~ .xt-content
  .xt-card:has(.xt-text-moonTitle),
#xt-t1:checked ~ .xt-content
  .xt-card:has(.xt-text-draftTitle) {
  display: none !important;
}

#xt-t2:checked ~ .xt-content
  .xt-card:has(.xt-text-rantTitle),
#xt-t2:checked ~ .xt-content
  .xt-card:has(.xt-text-draftTitle) {
  display: none !important;
}

#xt-t3:checked ~ .xt-content
  .xt-card:has(.xt-text-rantTitle),
#xt-t3:checked ~ .xt-content
  .xt-card:has(.xt-text-moonTitle) {
  display: none !important;
}


/* ==========================================================
   18. 底部
   ========================================================== */

.xt-footer {
  display: block !important;

  width: 100%;

  margin: 0 !important;
